/**
 * @import {AtRule, ChildNode, Container, Declaration, PluginCreator, Root, Rule} from 'postcss'
 * @import {Pseudo, Root as SelectorRoot, Selector} from 'postcss-selector-parser'
 * @import {Node as ValueNode} from 'postcss-value-parser'
 */
import type { ChildNode, Container, PluginCreator } from 'postcss';
export type DuplicatedValuesMode = true | 'syntax';
export type Options = KeepDuplicatedOptions | RemoveDuplicatedPropertiesOptions | RemoveDuplicatedValuesOptions;
export type KeepDuplicatedOptions = {
    /**
     * Keep every duplicated
     * declaration.
     */
    removeDuplicatedProperties?: false;
    /**
     * Keep every duplicated
     * declaration.
     */
    removeDuplicatedValues?: false;
};
export type RemoveDuplicatedPropertiesOptions = {
    /**
     * Keep only the last declaration
     * of each property, or the last `!important` one when an earlier
     * declaration has the flag.
     */
    removeDuplicatedProperties: true;
    /**
     * Off, because only one of the
     * two options can be set.
     */
    removeDuplicatedValues?: false;
};
export type RemoveDuplicatedValuesOptions = {
    /**
     * Off, because only one of
     * the two options can be set.
     */
    removeDuplicatedProperties?: false;
    /**
     * Remove duplicated
     * declarations; see {@link DuplicatedValuesMode}.
     */
    removeDuplicatedValues: DuplicatedValuesMode;
};
export type ValueShape = string | Array<ValueShape>;
export type Parent = Container & {
    nodes: Array<ChildNode>;
};
/**
 * Combine rules with equivalent selectors in the same context, and optionally
 * remove duplicated declarations.
 *
 * @example
 *   import postcss from 'postcss';
 *   import combineSelectors from 'postcss-combine-duplicated-selectors';
 *
 *   postcss([combineSelectors({ removeDuplicatedValues: true })]);
 *
 * @type {PluginCreator<Options>}
 */
declare const plugin: PluginCreator<Options>;
export default plugin;
